insert into public.perfil (id, dados) values (1, $json${"nome":"Giovanna da Rocha Bragion","apelido":"Lua","frase":"Estudante de Oceanografia na USP e pesquisadora de iniciação científica. Investigo como os microplásticos carregam metais pelo litoral, do Paraná às Ilhas Canárias.","sobre":["Sou estudante de graduação em Oceanografia no Instituto Oceanográfico da Universidade de São Paulo (IOUSP).","Faço iniciação científica com bolsa da FAPESP no **ProxyMar**, o Laboratório de Proxies Marinhos para o Futuro do Oceano, no IOUSP. Minha pesquisa estuda os **microplásticos** e os **metais** que ficam presos na superfície deles em praias e sedimentos costeiros.","Em 2026 levei essa pesquisa para a Universidad de La Laguna, em Tenerife, nas Ilhas Canárias, para comparar o litoral do Paraná com o de lá.","Este espaço é o meu caderno de campo: cada experiência vira um registro, com fotos, lugares e o que aprendi."],"formacao":[{"titulo":"Graduação em Oceanografia (em andamento)","lugar":"Universidade de São Paulo (IOUSP)","periodo":"2024 – atual"},{"titulo":"Intercâmbio de pesquisa","lugar":"Universidad de La Laguna, Tenerife (Espanha)","periodo":"2026"},{"titulo":"Curso de Poluição Marinha (6 h)","lugar":"Instituto Oceanográfico da USP","periodo":"2024"},{"titulo":"Ensino Médio","lugar":"Etec Comendador João Rays","periodo":"2021 – 2023"}],"competencias":["Extração e triagem de microplásticos","Estereomicroscopia","Espectroscopia FTIR","Digestão ácida (USEPA 3050B)","ICP-OES e ICP-MS","Coleta de sedimentos costeiros"],"idiomas":["Português (nativo)","Inglês (avançado)","Espanhol (intermediário)"],"contatos":{"email":"email@exemplo.com","linkedin":"https://www.linkedin.com/","lattes":"http://lattes.cnpq.br/4550484678979000","instagram":"https://www.instagram.com/gi_bragion_/"},"curriculo":"#","fotoPerfil":{"cena":"mata","seed":3},"marcos":[{"data":"2023-12-01","titulo":"Conclusão do Ensino Médio","texto":"Etec Comendador João Rays."},{"data":"2024-02-01","titulo":"Entrada no IOUSP","texto":"Começo da graduação em Oceanografia na USP."},{"data":"2024-11-01","titulo":"Primeira apresentação em congresso","texto":"Microplásticos e metais associados em praias do litoral do Paraná."}]}$json$::jsonb)
on conflict (id) do update set dados = excluded.dados;

delete from public.posts where slug like 'exemplo-%';

insert into public.posts (slug, titulo, data, local, lat, lon, categoria, resumo, texto, diario, fotos, publicado) values
  ('exemplo-tenerife', 'Microplásticos do outro lado do Atlântico', '2026-03-01', 'Universidad de La Laguna, Tenerife, Ilhas Canárias', 28.48, -16.32, 'intercambio', 'Levei minha pesquisa para Tenerife e comparei os metais presos em microplásticos das praias das Canárias com os do litoral do Paraná.', 'Em 2026 fui para a Universidad de La Laguna, em Tenerife, para um estudo comparativo: a mesma metodologia aplicada em sedimentos costeiros do **Paraná** e das **Ilhas Canárias**.

Coletamos sedimentos superficiais, extraímos e triamos os microplásticos, e identificamos o tipo (fragmentos, fibras, pellets) e o polímero de cada um com estereomicroscopia e FTIR.

Usar o mesmo método nos dois lados do Atlântico ajuda a entender o que muda de um ambiente para o outro: o formato da partícula, o tipo de plástico ou as condições da costa.

*Trabalho feito com a orientação da Profa. Renata Hanae Nagai (IOUSP) e a colaboração de Javier Hernández-Borges (ULL), com bolsa da FAPESP.*', null, $json$[{"cena":"falesia","seed":1,"legenda":"Costa de Tenerife"},{"cena":"costao","seed":2,"legenda":"Praia de rocha vulcânica"},{"cena":"montanha","seed":4,"legenda":"Paisagem vulcânica"},{"cena":"mar","seed":5,"legenda":"Atlântico"}]$json$::jsonb, true),
  ('exemplo-superagui', 'Coletas na Ilha do Superagui e em Pontal do Sul', '2025-07-01', 'Ilha do Superagui, Paraná', -25.46, -48.25, 'campo', 'As duas praias do litoral do Paraná onde coleto os sedimentos da minha iniciação científica.', 'A minha pesquisa acontece em duas praias do litoral paranaense: a **Ilha do Superagui** e **Pontal do Sul**. As coletas de sedimento são sazonais, para ver se o que encontramos muda ao longo do ano.

Em campo, o trabalho é recolher o sedimento da praia de forma padronizada. Depois, no laboratório, as amostras são peneiradas e triadas, e os microplásticos são separados com técnicas como o teste da agulha quente.', null, $json$[{"cena":"praia","seed":13,"legenda":"Faixa de areia"},{"cena":"mata","seed":10,"legenda":"Caminho até a praia"},{"cena":"costao","seed":9,"legenda":"Pontal do Sul"}]$json$::jsonb, true),
  ('exemplo-proxymar', 'Metais presos em microplásticos: minha IC na FAPESP', '2025-03-01', 'Laboratório ProxyMar, IOUSP, São Paulo', -23.56, -46.72, 'pesquisa', 'Como os microplásticos podem carregar metais pesados pelas praias, e como a gente mede isso no laboratório.', 'Microplásticos são partículas de plástico menores que 5 mm. Na praia, eles podem funcionar como pequenos "carregadores" de metais pesados, que ficam presos na superfície deles.

Na minha iniciação científica, com bolsa da FAPESP no **ProxyMar**, eu caracterizo a composição química dos microplásticos e meço os metais adsorvidos (Al, Cd, Cr, Cu, Fe, Mn, Sn, Ti e Zn) usando **ICP-OES** e **ICP-MS**.

Os primeiros resultados já confirmaram metais presos em pellets plásticos das praias estudadas. O próximo passo é relacionar o tipo de partícula com a quantidade de metal e ver se isso muda com as estações do ano.', null, $json$[{"cena":"lua","seed":7,"legenda":"Noites de laboratório"},{"cena":"mar","seed":8,"legenda":"De onde vêm as amostras"}]$json$::jsonb, true),
  ('exemplo-sediment-profile', 'Fotografando o fundo do mar na costa de São Paulo', '2025-05-01', 'Plataforma continental de São Paulo', -24.05, -46.3, 'embarques', 'Participei dos primeiros registros com Sediment Profile Imagery na costa paulista, uma câmera que fotografa o sedimento por dentro.', 'A *Sediment Profile Imagery* é uma câmera que desce até o fundo, entra no sedimento e tira uma foto do perfil, como se fosse um corte lateral do fundo do mar.

Participei dos primeiros registros desse método na região costeira de São Paulo. O trabalho virou um resumo apresentado no **VII Simpósio Brasileiro de Geologia e Geofísica Marinha**, em Vitória (ES).', $json${"navio":"Embarcação do IOUSP","coordenadas":"Costa de São Paulo","profundidade":"plataforma interna","dias":"1"}$json$::jsonb, $json$[{"cena":"navio","seed":6,"legenda":"Saída para o embarque"},{"cena":"mar","seed":14,"legenda":"Ponto de coleta"}]$json$::jsonb, true),
  ('exemplo-pub-antartica', 'Primeira pesquisa: do Atlântico Sul à Antártica', '2024-09-01', 'Instituto Oceanográfico da USP, São Paulo', -23.555, -46.73, 'pesquisa', 'Minha primeira bolsa de pesquisa, estudando microplásticos e metais em ambientes costeiros do Atlântico Sul e da Antártica.', 'Entre 2024 e 2025 fiz minha primeira pesquisa, com bolsa do Programa Unificado de Bolsas da USP: "Microplásticos e metais associados no ambiente costeiro do Atlântico Sul e Antártica".

Foi onde aprendi as técnicas que uso até hoje: extração de microplásticos, estereomicroscopia, digestão ácida e espectrometria (ICP-OES/MS).', null, $json$[{"cena":"por-do-sol","seed":11,"legenda":"Fim de tarde no IOUSP"}]$json$::jsonb, true),
  ('exemplo-siicusp', 'Apresentando no SIICUSP e no Congresso Brasileiro de Geoquímica', '2025-10-01', 'Universidade de São Paulo, São Paulo', -23.56, -46.73, 'eventos', 'Em 2025 apresentei meu trabalho sobre microplásticos e metais em dois eventos científicos.', 'Apresentei o trabalho "Microplásticos e metais associados em ambientes costeiros do Atlântico Sul e da Antártica" no **Simpósio Internacional de Iniciação Científica e Tecnológica da USP (SIICUSP)** e no **Congresso Brasileiro de Geoquímica**.

Também participei do Workshop sobre o talude continental da Bacia de Santos e, em 2026, do II Seminário sobre Monitoramento de Microplásticos.', null, $json$[{"cena":"por-do-sol","seed":15,"legenda":"Dia de apresentação"}]$json$::jsonb, true);

